Fn::Join:
{
  "Comment": "Radio Player State Machine - Controls player state transitions and command orchestration",
  "StartAt": "ParseCommand",
  "States": {
    "ParseCommand": {
      "Type": "Pass",
      "Comment": "Extract command details from IoT message",
      "Parameters": {
        "command.$": "$.command",
        "playerId.$": "$.playerId",
        "timestamp.$": "$.timestamp"
      },
      "Next": "RouteCommand"
    },

    "RouteCommand": {
      "Type": "Choice",
      "Comment": "Route to appropriate handler based on command type",
      "Choices": [
        {
          "Variable": "$.command",
          "StringEquals": "LOAD",
          "Next": "HandleLoadCommand"
        },
        {
          "Variable": "$.command",
          "StringEquals": "PLAY",
          "Next": "HandlePlayCommand"
        },
        {
          "Variable": "$.command",
          "StringEquals": "PAUSE",
          "Next": "HandlePauseCommand"
        },
        {
          "Variable": "$.command",
          "StringEquals": "STOP",
          "Next": "HandleStopCommand"
        },
        {
          "Variable": "$.command",
          "StringEquals": "UNLOAD",
          "Next": "HandleUnloadCommand"
        }
      ],
      "Default": "UnknownCommand"
    },

    "HandleLoadCommand": {
      "Type": "Task",
      "Comment": "Process LOAD command - fetch playlist and track data",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "

",
        "Payload": {
          "command.$": "$.command",
          "playerId.$": "$.playerId",
          "timestamp.$": "$.timestamp"
        }
      },
      "ResultPath": "$.loadResult",
      "Next": "ValidateLoadResult",
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "Next": "HandleError",
          "ResultPath": "$.error"
        }
      ]
    },

    "ValidateLoadResult": {
      "Type": "Choice",
      "Comment": "Check if track data was successfully loaded",
      "Choices": [
        {
          "Variable": "$.loadResult.Payload.success",
          "BooleanEquals": true,
          "Next": "PublishLoadResponse"
        }
      ],
      "Default": "HandleError"
    },

    "PublishLoadResponse": {
      "Type": "Task",
      "Comment": "Publish LOAD command response with track data to IoT via Lambda",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "

",
        "Payload": {
          "topic.$": "States.Format('radio/player/{}/command', $.playerId)",
          "message": {
            "command": "LOAD",
            "playerId.$": "$.playerId",
            "timestamp.$": "$$.State.EnteredTime",
            "params": {
              "playlist.$": "$.loadResult.Payload.playlist",
              "schedule.$": "$.loadResult.Payload.schedule",
              "currentTrack.$": "$.loadResult.Payload.currentTrack",
              "track.$": "$.loadResult.Payload.track"
            }
          }
        }
      },
      "ResultPath": "$.publishResult",
      "Next": "CommandSuccess",
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "Next": "HandleError",
          "ResultPath": "$.error"
        }
      ]
    },

    "HandlePlayCommand": {
      "Type": "Task",
      "Comment": "Process PLAY command - validate state and respond",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "

",
        "Payload": {
          "topic.$": "States.Format('radio/player/{}/command', $.playerId)",
          "message": {
            "command.$": "$.result.Payload.command",
            "playerId.$": "$.playerId",
            "timestamp.$": "$$.State.EnteredTime"
          }
        }
      },
      "ResultPath": "$.publishResult",
      "Next": "CommandSuccess"
    },

    "UnknownCommand": {
      "Type": "Fail",
      "Comment": "Unknown command type received",
      "Error": "UnknownCommandError",
      "Cause": "The command type is not recognized by the state machine"
    },

    "HandleError": {
      "Type": "Task",
      "Comment": "Handle errors and publish error response to IoT",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "

",
        "Payload": {
          "topic.$": "States.Format('radio/player/{}/command', $.playerId)",
          "message": {
            "command": "ERROR",
            "playerId.$": "$.playerId",
            "timestamp.$": "$$.State.EnteredTime",
            "error": {
              "message.$": "$.error.Cause",
              "originalCommand.$": "$.command"
            }
          }
        }
      },
      "ResultPath": "$.errorPublishResult",
      "Next": "CommandFailed"
    },

    "CommandSuccess": {
      "Type": "Succeed",
      "Comment": "Command processed successfully"
    },

    "CommandFailed": {
      "Type": "Fail",
      "Comment": "Command processing failed",
      "Error": "CommandProcessingError",
      "Cause": "Failed to process player command"
    }
  }
}
